/// Each API type reads its fixtures (one sample per type, per variant for enums) and writes them back unchanged:
/// the generator's idea of the JSON form is serde's. The Dart client is held to the same fixtures.
#[cfg(test)]
mod fixtures {
    fn round_trip<T: ::serde::Serialize + ::serde::de::DeserializeOwned>(
        all: &::serde_json::Value,
        name: &str,
    ) {
        let samples = all[name]
            .as_array()
            .unwrap_or_else(|| panic!("no fixtures for {name}"));
        for v in samples {
            let t: T = ::serde_json::from_value(v.clone())
                .unwrap_or_else(|e| panic!("{name} does not read {v}: {e}"));
            let back = ::serde_json::to_value(&t)
                .unwrap_or_else(|e| panic!("{name} does not write: {e}"));
            assert_eq!(back, * v, "{name} reads {v} but writes {back}");
        }
    }
    #[test]
    fn every_api_type_reads_and_writes_its_fixtures() {
        let all: ::serde_json::Value = ::serde_json::from_str(
                include_str!("../fixtures.generated.json"),
            )
            .expect("the fixtures are JSON");
        round_trip::<::post_core::Device>(&all, "Device");
        round_trip::<::post_core::Invite>(&all, "Invite");
        round_trip::<::post_core::Message>(&all, "Message");
        round_trip::<::post_core::Presence>(&all, "Presence");
        round_trip::<::post_core::Fill>(&all, "Fill");
        round_trip::<::post_core::Event>(&all, "Event");
        round_trip::<::post_core::kinds::PictureKind>(&all, "PictureKind");
    }
}
